def moving_average(xs, k):
    if k <= 0:
        raise ValueError("k must be positive")
    if not xs or k > len(xs):
        return []
    out = []
    for i in range(len(xs) - k + 1):
        window = xs[i:i + k]
        out.append(sum(window) / k)
    return out
